from datetime import datetime, timezone
from telemetry.exceptions import ClockSkewError, NonUTCError, MAX_SKEW_SECONDS

def validate_and_normalize_event(event: dict, reference_time: datetime) -> dict:
    if reference_time.tzinfo is None or reference_time.utcoffset() != timezone.utc.utcoffset(reference_time):
        raise NonUTCError('Reference time must be timezone-aware UTC')
    raw_ts = event.get('timestamp')
    if isinstance(raw_ts, str):
        if raw_ts.endswith('Z'):
            raw_ts = raw_ts[:-1] + '+00:00'
        try:
            dt = datetime.fromisoformat(raw_ts)
        except Exception as e:
            raise NonUTCError(f'Invalid timestamp format: {e}')
    elif isinstance(raw_ts, datetime):
        dt = raw_ts
    else:
        raise NonUTCError('Timestamp must be datetime or ISO string')
    if dt.tzinfo is None or dt.utcoffset() != timezone.utc.utcoffset(dt):
        raise NonUTCError('Event timestamp must be timezone-aware UTC')
    skew = abs((dt - reference_time).total_seconds())
    if skew > MAX_SKEW_SECONDS:
        raise ClockSkewError(f'Clock skew {skew}s exceeds MAX_SKEW_SECONDS ({MAX_SKEW_SECONDS}s)')
    iso_z = dt.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    return {
        'event_id': event['event_id'],
        'timestamp': iso_z,
        'payload': event.get('payload', {}),
    }

