reference_solution.resilience/policy.py:
import time
from resilience.errors import (
    FatalClientError,
    TransientNetworkError,
    RetryExhaustedError,
    INITIAL_BACKOFF_SECONDS,
    BACKOFF_FACTOR,
    MAX_BACKOFF_SECONDS,
    MAX_ATTEMPTS,
)

def execute_with_retry(func, *args, sleep_fn=None, **kwargs):
    sleeper = sleep_fn if sleep_fn is not None else time.sleep
    last_err = None
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            return func(*args, **kwargs)
        except FatalClientError:
            raise
        except TransientNetworkError as exc:
            last_err = exc
            if attempt < MAX_ATTEMPTS:
                delay = min(MAX_BACKOFF_SECONDS, INITIAL_BACKOFF_SECONDS * (BACKOFF_FACTOR ** (attempt - 1)))
                sleeper(delay)
            else:
                raise RetryExhaustedError(f'Failed after {MAX_ATTEMPTS} attempts') from last_err

