from cache.constants import InvalidPriorityError, DEFAULT_CAPACITY, PRIORITY_NORMAL

class PriorityLfuCache:
    def __init__(self, capacity: int = DEFAULT_CAPACITY):
        self.capacity = capacity
        self._store = {}
        self._freq = {}
        self._priority = {}
        self._tick = 0
        self._last_access = {}

    def put(self, key: str, value, priority: int = PRIORITY_NORMAL):
        if priority < 0 or priority > 2:
            raise InvalidPriorityError(f"Invalid priority {priority}")
        self._tick += 1
        if key in self._store:
            self._store[key] = value
            self._priority[key] = priority
            self._freq[key] += 1
            self._last_access[key] = self._tick
            return
        if len(self._store) >= self.capacity:
            candidate = min(self._store.keys(), key=lambda k: (self._freq[k], self._last_access[k]))
            del self._store[candidate]
            del self._freq[candidate]
            del self._priority[candidate]
            del self._last_access[candidate]
        self._store[key] = value
        self._priority[key] = priority
        self._freq[key] = 1
        self._last_access[key] = self._tick

    def get(self, key: str, default=None):
        if key not in self._store:
            return default
        self._tick += 1
        self._freq[key] += 1
        self._last_access[key] = self._tick
        return self._store[key]

    def size(self) -> int:
        return len(self._store)

