reference_solution.net/alpn.py:
from net.exceptions import ProtocolNegotiationError

def negotiate_alpn(client_protocols: list[str], allow_fallback: bool = False, upgrade_token: str | None = None) -> str:
    if not isinstance(client_protocols, list) or not client_protocols:
        raise ProtocolNegotiationError("No protocols offered")
    if "h2" in client_protocols:
        return "h2"
    if allow_fallback and upgrade_token == "EDGE_FALLBACK_OK":
        if "http/1.1" in client_protocols:
            return "http/1.1"
        return "http/1.1"
    raise ProtocolNegotiationError("HTTP/2 mandatory; fallback not authorized")

