import sys

def run_test(sol_dir='.'):
    sys.path.insert(0, sol_dir)
    for m in ['net.exceptions', 'net.alpn', 'net']:
        if m in sys.modules: del sys.modules[m]
    from net.alpn import negotiate_alpn
    from net.exceptions import ProtocolNegotiationError
    assert negotiate_alpn(["h2", "http/1.1"]) == "h2"
    assert negotiate_alpn(["h2"]) == "h2"
    assert negotiate_alpn(["http/1.1"], allow_fallback=True, upgrade_token="EDGE_FALLBACK_OK") == "http/1.1"
    try:
        negotiate_alpn(["http/1.1"], allow_fallback=False)
        assert False, "Should raise ProtocolNegotiationError without fallback"
    except ProtocolNegotiationError:
        pass
    try:
        negotiate_alpn(["http/1.1"], allow_fallback=True, upgrade_token="WRONG")
        assert False, "Should raise ProtocolNegotiationError with invalid token"
    except ProtocolNegotiationError:
        pass
    try:
        negotiate_alpn([])
        assert False, "Should raise ProtocolNegotiationError on empty"
    except ProtocolNegotiationError:
        pass
    print("PASS")

if __name__ == '__main__':
    sol_dir = sys.argv[1] if len(sys.argv) > 1 else '.'
    run_test(sol_dir)

