reference_solution.auth/token_validator.py:
from auth.errors import TokenValidationError, InsecureAlgorithmError

def validate_jwt_header(header: dict) -> bool:
    if not isinstance(header, dict):
        raise TokenValidationError("Invalid header format")
    alg = header.get("alg")
    if alg == "HS256":
        raise InsecureAlgorithmError("HS256 is deprecated and forbidden")
    if alg != "RS256":
        raise TokenValidationError("Algorithm must be RS256")
    kid = header.get("kid")
    if not isinstance(kid, str) or not kid.strip():
        raise TokenValidationError("Missing or invalid kid")
    return True

