reference_solution.storage/pragmas.py:
from storage.errors import StorageEngineError

def get_db_pragmas(profile: str = "production") -> list[str]:
    if profile == "legacy_full":
        raise StorageEngineError("FULL synchronous mode is deprecated and forbidden")
    if profile == "production":
        return [
            "PRAGMA journal_mode = WAL;",
            "PRAGMA synchronous = NORMAL;",
            "PRAGMA busy_timeout = 5000;",
            "PRAGMA foreign_keys = ON;",
        ]
    if profile == "memory":
        return [
            "PRAGMA journal_mode = MEMORY;",
            "PRAGMA synchronous = OFF;",
        ]
    raise StorageEngineError(f"Unknown storage profile {profile}")

