reference_solution.ratelimit/bucket.py:
from ratelimit.errors import RateLimitValueError

class TokenBucket:
    def __init__(self, capacity: float, refill_rate: float, now: float = 0.0):
        if capacity <= 0 or refill_rate <= 0:
            raise RateLimitValueError("Capacity and refill rate must be positive")
        self.capacity = float(capacity)
        self.refill_rate = float(refill_rate)
        self.tokens = float(capacity)
        self.last_update = float(now)

    def consume(self, tokens: float = 1.0, now: float | None = None) -> bool:
        if tokens <= 0:
            raise RateLimitValueError("Tokens must be positive")
        current_time = self.last_update if now is None else float(now)
        if current_time > self.last_update:
            elapsed = current_time - self.last_update
            self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_rate)
            self.last_update = current_time
        if self.tokens >= tokens:
            self.tokens -= tokens
            return True
        return False

