import math
from metrics.errors import InvalidMetricValueError

class ExponentialHistogram:
    def __init__(self, max_buckets: int = 16):
        if max_buckets <= 0:
            raise InvalidMetricValueError("max_buckets must be positive")
        self.max_buckets = max_buckets
        self._counts = {}
        self._total = 0

    def record(self, val: float) -> int:
        if not isinstance(val, (int, float)) or val <= 0.0 or math.isnan(val):
            raise InvalidMetricValueError("Value must be positive number")
        idx = max(0, min(self.max_buckets - 1, math.floor(math.log2(val))))
        self._counts[idx] = self._counts.get(idx, 0) + 1
        self._total += 1
        return idx

    def bucket_counts(self) -> dict[int, int]:
        return dict(self._counts)

    def total_count(self) -> int:
        return self._total

