import hashlib
from crypto.errors import InsecureKdfParametersError

def derive_encryption_key(password: str, salt: bytes, iterations: int = 100000, key_length: int = 32) -> bytes:
    if not isinstance(password, str) or not password:
        raise InsecureKdfParametersError("Empty password")
    if not isinstance(salt, bytes) or len(salt) < 16:
        raise InsecureKdfParametersError("Salt must be at least 16 bytes")
    if iterations < 100000:
        raise InsecureKdfParametersError("Iterations must be >= 100000")
    if key_length not in (16, 24, 32):
        raise InsecureKdfParametersError("Key length must be 16, 24, or 32 bytes")
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations, dklen=key_length)

