import sys

def run_test(sol_dir='.'):
    sys.path.insert(0, sol_dir)
    for m in ['crypto.errors', 'crypto.kdf', 'crypto']:
        if m in sys.modules: del sys.modules[m]
    from crypto.kdf import derive_encryption_key
    from crypto.errors import InsecureKdfParametersError
    salt = b"0123456789abcdef"
    k1 = derive_encryption_key("secret-pass", salt, iterations=100000, key_length=32)
    assert isinstance(k1, bytes) and len(k1) == 32
    k2 = derive_encryption_key("secret-pass", salt, iterations=100000, key_length=16)
    assert len(k2) == 16
    try:
        derive_encryption_key("", salt)
        assert False, "Should raise InsecureKdfParametersError for empty password"
    except InsecureKdfParametersError:
        pass
    try:
        derive_encryption_key("secret-pass", b"short_salt")
        assert False, "Should raise InsecureKdfParametersError for short salt"
    except InsecureKdfParametersError:
        pass
    try:
        derive_encryption_key("secret-pass", salt, iterations=50000)
        assert False, "Should raise InsecureKdfParametersError for low iterations"
    except InsecureKdfParametersError:
        pass
    try:
        derive_encryption_key("secret-pass", salt, key_length=64)
        assert False, "Should raise InsecureKdfParametersError for invalid key length"
    except InsecureKdfParametersError:
        pass
    print("PASS")

if __name__ == '__main__':
    sol_dir = sys.argv[1] if len(sys.argv) > 1 else '.'
    run_test(sol_dir)

