from typing import Any
from schema.errors import SchemaValidationError

def validate_record(record: dict[str, Any], schema: dict[str, type], allow_extra: bool = False) -> bool:
    if not isinstance(record, dict) or not isinstance(schema, dict):
        raise SchemaValidationError("Record and schema must be dictionaries")
    for key, expected_type in schema.items():
        if key not in record:
            raise SchemaValidationError(f"Missing required field {key}")
        if not isinstance(record[key], expected_type):
            raise SchemaValidationError(f"Type mismatch for {key}")
    if not allow_extra:
        extra = set(record.keys()) - set(schema.keys())
        if extra:
            raise SchemaValidationError(f"Unexpected extra field {next(iter(extra))}")
    return True

