from cron.errors import CronSyntaxError

def parse_cron_field(expr: str, min_val: int, max_val: int) -> list[int]:
    if not isinstance(expr, str) or not expr.strip():
        raise CronSyntaxError("Empty cron expression")
    expr = expr.strip()
    result = set()
    parts = expr.split(",")
    for part in parts:
        part = part.strip()
        if not part:
            raise CronSyntaxError("Empty subpart")
        if part == "*":
            result.update(range(min_val, max_val + 1))
        elif part.startswith("*/"):
            try:
                step = int(part[2:])
            except ValueError:
                raise CronSyntaxError(f"Invalid step: {part}")
            if step <= 0:
                raise CronSyntaxError("Step must be positive")
            result.update(range(min_val, max_val + 1, step))
        elif "-" in part:
            sub = part.split("-")
            if len(sub) != 2:
                raise CronSyntaxError(f"Invalid range: {part}")
            try:
                start = int(sub[0])
                end = int(sub[1])
            except ValueError:
                raise CronSyntaxError(f"Invalid range integers: {part}")
            if start > end or start < min_val or end > max_val:
                raise CronSyntaxError(f"Range out of bounds: {part}")
            result.update(range(start, end + 1))
        else:
            try:
                val = int(part)
            except ValueError:
                raise CronSyntaxError(f"Invalid integer: {part}")
            if val < min_val or val > max_val:
                raise CronSyntaxError(f"Value out of bounds: {val}")
            result.add(val)
    return sorted(result)

