from typing import Callable
from gateway.errors import GatewayConfigurationError, RateLimitExceededError, CircuitBreakerOpenError

class GatewayDispatcher:
    def __init__(self, rate_limit: int = 10, failure_threshold: int = 3):
        self.remaining_quota = rate_limit
        self.failure_threshold = failure_threshold
        self.consecutive_failures = 0
        self.circuit_open = False
        self.routes = {}

    def register(self, prefix: str, handler: Callable[[str], str]) -> None:
        if not isinstance(prefix, str) or not prefix.strip():
            raise GatewayConfigurationError("Prefix must be non-empty string")
        if prefix in self.routes:
            raise GatewayConfigurationError(f"Duplicate prefix: {prefix}")
        self.routes[prefix] = handler

    def dispatch(self, path: str, is_error: bool = False) -> str:
        if self.circuit_open:
            raise CircuitBreakerOpenError("Circuit breaker is OPEN")
        if self.remaining_quota <= 0:
            raise RateLimitExceededError("Rate limit exceeded")
        self.remaining_quota -= 1

        if is_error:
            self.consecutive_failures += 1
            if self.consecutive_failures >= self.failure_threshold:
                self.circuit_open = True
            return "ERROR"

        self.consecutive_failures = 0
        # Longest prefix match
        matching = sorted([p for p in self.routes if path.startswith(p)], key=len, reverse=True)
        if not matching:
            return "NOT_FOUND"
        return self.routes[matching[0]](path)

