import zlib
from pubsub.errors import PublisherError

class PartitionedPublisher:
    def __init__(self, num_partitions: int = 4, max_retries: int = 3):
        if num_partitions <= 0 or max_retries < 0:
            raise PublisherError("Invalid publisher parameters")
        self.num_partitions = num_partitions
        self.max_retries = max_retries
        self.total_published = 0
        self.dlq_count = 0

    def publish(self, key: str, payload: str, simulate_failure: bool = False) -> tuple[int, bool]:
        if not isinstance(key, str) or not key or not isinstance(payload, str) or not payload:
            raise PublisherError("Key and payload must be non-empty strings")
        partition = (zlib.crc32(key.encode("utf-8")) & 0xFFFFFFFF) % self.num_partitions
        if simulate_failure:
            self.dlq_count += 1
            return (-1, True)
        self.total_published += 1
        return (partition, False)

