import re
from telemetry.errors import InvalidMetricNameError, MetricFormattingError

_NAME_RE = re.compile(r"^[a-zA-Z_:][a-zA-Z0-9_:]*$")

def format_prometheus_metric(name: str, labels: dict[str, str], value: float, timestamp_ms: int | None = None) -> str:
    if not isinstance(name, str) or not _NAME_RE.match(name):
        raise InvalidMetricNameError(f"Invalid metric name: {name}")
    if timestamp_ms is not None and timestamp_ms < 0:
        raise MetricFormattingError("Timestamp must be non-negative")
    label_str = ""
    if labels:
        parts = []
        for k in sorted(labels.keys()):
            v = str(labels[k])
            v_esc = v.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
            parts.append(f'{k}="{v_esc}"')
        label_str = "{" + ",".join(parts) + "}"
    val_str = str(value)
    if timestamp_ms is not None:
        return f"{name}{label_str} {val_str} {timestamp_ms}"
    return f"{name}{label_str} {val_str}"

