from typing import Callable, Any
from pool.errors import PoolExhaustedError

class ConnectionPool:
    def __init__(self, factory: Callable[[], Any], max_size: int = 5, max_age_s: float = 60.0):
        self.factory = factory
        self.max_size = max_size
        self.max_age_s = max_age_s
        self.available: list[tuple[Any, float]] = []
        self.in_use: set[Any] = set()

    def acquire(self, now: float = 0.0) -> Any:
        while self.available:
            conn, created_at = self.available.pop()
            if hasattr(conn, "is_alive") and not conn.is_alive():
                if hasattr(conn, "close"):
                    conn.close()
                continue
            if (now - created_at) > self.max_age_s:
                if hasattr(conn, "close"):
                    conn.close()
                continue
            self.in_use.add(conn)
            return conn

        if len(self.in_use) >= self.max_size:
            raise PoolExhaustedError("Connection pool exhausted")
        conn = self.factory()
        self.in_use.add(conn)
        return conn

    def release(self, conn: Any) -> None:
        if conn in self.in_use:
            self.in_use.remove(conn)
            self.available.append((conn, 0.0))

    def size(self) -> int:
        return len(self.available) + len(self.in_use)

