from taskqueue.errors import DuplicateTaskError, InvalidTaskError

class PriorityTaskQueue:
    def __init__(self):
        self._items = []
        self._ids = set()
        self._seq = 0

    def push(self, task_id: str, priority: int, weight: int) -> None:
        if not isinstance(task_id, str) or not task_id:
            raise InvalidTaskError("task_id must be non-empty string")
        if not isinstance(weight, int) or weight <= 0:
            raise InvalidTaskError("Weight must be positive integer")
        if task_id in self._ids:
            raise DuplicateTaskError(f"Task {task_id} already queued")
        self._seq += 1
        entry = (priority, self._seq, weight, task_id)
        self._items.append(entry)
        self._items.sort(key=lambda x: (x[0], x[1]))
        self._ids.add(task_id)

    def pop(self) -> str | None:
        if not self._items:
            return None
        _, _, _, task_id = self._items.pop(0)
        self._ids.remove(task_id)
        return task_id

    def drain_batch(self, max_weight: int) -> list[str]:
        if max_weight <= 0:
            return []
        drained = []
        cum_weight = 0
        while self._items:
            priority, seq, weight, task_id = self._items[0]
            if cum_weight + weight > max_weight:
                break
            self._items.pop(0)
            self._ids.remove(task_id)
            drained.append(task_id)
            cum_weight += weight
        return drained

    def size(self) -> int:
        return len(self._items)
